var a=`1246-rice-and-peas`;var n=`world-1246`;var t=`JM`;var r=`central-america-caribbean`;var s=4;var o=549;var d={en:`Rice and Peas`,ua:`Рис із горохом`};var c={en:`Rice and Peas is a dish from Jamaica featuring kidney beans, green onion, garlic, thyme. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рис із горохом, страва кухні країни Ямайка з такими основними складниками: червона квасоля кідні, зелена цибуля, часник, чебрець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Soak the dried beans in ample clean cold water for about 420 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 420 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:420,i:[[`kidney-beans`,360,`g`],[`water`,950,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 95 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 95 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:95,i:[[`water`,1050,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`green-onion`,70,`g`],[`garlic`,4,`clove`],[`thyme`,3,`sprig`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 26 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 26 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`white-rice`,410,`g`],[`coconut-milk`,420,`ml`],[`water`,300,`ml`],[`allspice-berries`,6,`pcs`]]}];var u={slug:a,id:n,country:`JM`,region:r,servings:4,minutes:549,title:d,text:c,steps:l};export{t as country,u as default,n as id,o as minutes,r as region,s as servings,a as slug,l as steps,c as text,d as title};